// Mock backend for running the UI in a plain browser. Serves data generated by
// scripts/build-mock.mjs from the handoff prototype, simulates indexing, jobs and the AI flow.
// URL parameters (all optional):
//   files=12000    replace the repo tree with a generated one of that many files
//   modules=5000   replace the module map with a generated one of that many modules
//   fanout=2       average imports per generated module (real repos run 10 to 30)
//   latency=15     milliseconds added to every call
//   index=0        skip the simulated indexing run
//   ai=on          start signed in, with AI on for the repo
import type { Backend, BackendEvents, EventName } from "../api";
import type { AiStatus } from "../bindings/AiStatus";
import type { Architecture } from "../bindings/Architecture";
import type { ChangeReview } from "../bindings/ChangeReview";
import type { Comparison } from "../bindings/Comparison";
import type { FileView } from "../bindings/FileView";
import type { FlowUnit } from "../bindings/FlowUnit";
import type { FnCard } from "../bindings/FnCard";
import type { JobsState } from "../bindings/JobsState";
import type { ModuleInfo } from "../bindings/ModuleInfo";
import type { ModuleMap } from "../bindings/ModuleMap";
import type { RepoSummary } from "../bindings/RepoSummary";
import type { SearchHit } from "../bindings/SearchHit";
import type { SymRef } from "../bindings/SymRef";
import type { TreeNode } from "../bindings/TreeNode";
import type { Tier } from "../bindings/Tier";
import type { Language } from "../bindings/Language";
import type { LangCount } from "../bindings/LangCount";
import data from "./data/mock.json";
import { generateModuleMap, generateTree } from "./generate";
import { createMockGit } from "./git";

/** The JSON stores u64 fields as plain numbers; these are the raw shapes before conversion. */
export type RawLangCount = Omit<LangCount, "lines"> & { lines: number };
export type RawRepo = Omit<RepoSummary, "lines" | "languages"> & { lines: number; languages: RawLangCount[] };
export type RawModuleInfo = Omit<ModuleInfo, "lines"> & { lines: number };
export type RawModuleMap = Omit<ModuleMap, "modules"> & { modules: RawModuleInfo[] };

interface MockFile {
  source: string;
  flows: Record<string, FlowUnit>;
  view: FileView;
}

const D = data as unknown as {
  repo: RawRepo;
  recent: string[];
  tree: TreeNode;
  moduleMap: RawModuleMap;
  files: Record<string, MockFile>;
};

const params = new URLSearchParams(typeof location !== "undefined" ? location.search : "");
const LATENCY = Number(params.get("latency") ?? 15);
const BIG_FILES = Number(params.get("files") ?? 0);
const BIG_MODULES = Number(params.get("modules") ?? 0);
const FANOUT = Number(params.get("fanout") ?? 2);
const SIMULATE_INDEX = params.get("index") !== "0";

const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));
const big = (n: number) => Math.round(n);
const clone = <T>(x: T): T => structuredClone(x);

function toRepoSummary(r: RawRepo): RepoSummary {
  return { ...r, lines: big(r.lines), languages: r.languages.map((l) => ({ ...l, lines: big(l.lines) })) };
}
function toModuleInfo(m: RawModuleInfo): ModuleInfo {
  return { ...m, lines: big(m.lines) };
}

export function createMockBackend(): Backend {
  const listeners = new Map<EventName, Set<(p: unknown) => void>>();
  let signInTimer: ReturnType<typeof setTimeout> | undefined;
  const emit = <E extends EventName>(e: E, p: BackendEvents[E]) => listeners.get(e)?.forEach((cb) => cb(p));

  let tree: TreeNode = BIG_FILES ? generateTree(BIG_FILES) : clone(D.tree);
  const moduleMap: RawModuleMap = BIG_MODULES ? generateModuleMap(BIG_MODULES, FANOUT) : clone(D.moduleMap);
  let repo: RawRepo = BIG_FILES ? summarize(tree) : clone(D.repo);
  const files: Record<string, MockFile> = clone(D.files);
  let jobs: JobsState = { queued: 0, running: 0, done: 0, failed: 0, cacheHits: 0, cacheMisses: 0, hitRate: 0, pendingFiles: [] };
  let architecture: Architecture | null = null;
  const reviews = new Map<string, ChangeReview>();
  // ai=on: signed in with AI on for the repo, as after a sign-in in an earlier session.
  let ai: AiStatus = params.get("ai") === "on" ? { sidecar: "ready", signedIn: true, user: "mock-user", models: [], enabledForRepo: true, mock: true, deviceCode: null, message: null } : { sidecar: "off", signedIn: false, user: null, models: [], enabledForRepo: false, mock: true, deviceCode: null, message: null };
  let nextJob = 1;
  let indexing = false;
  const git = createMockGit();
  const sourceOf = (path: string) => {
    try {
      return fileFor(path).source;
    } catch {
      return null;
    }
  };

  const leaves = (n: TreeNode, out: TreeNode[] = []) => {
    if (n.isDir) n.children.forEach((c) => leaves(c, out));
    else out.push(n);
    return out;
  };
  const findNode = (path: string): TreeNode | null => {
    let n: TreeNode | undefined = tree;
    for (const part of path.split("/")) {
      n = n?.children.find((c) => c.name === part);
      if (!n) return null;
    }
    return n ?? null;
  };
  const fileFor = (path: string): MockFile => {
    if (!files[path]) {
      const node = findNode(path);
      if (!node || node.isDir) throw new Error(`No such file: ${path}`);
      files[path] = generatedFile(node);
    }
    return files[path];
  };

  async function simulateIndex() {
    if (indexing) return;
    indexing = true;
    const all = leaves(tree);
    const total = all.length;
    const t0 = performance.now();
    const pending = all.filter((f) => f.status === "pending");
    pending.forEach((f) => (f.status = "pending"));
    const phases: [BackendEvents["index_progress"]["phase"], number][] = [
      ["walk", 300],
      ["parse", 1300],
      ["resolve", 500],
      ["graph", 300],
    ];
    jobs = { ...jobs, queued: pending.length, running: 1, pendingFiles: pending.map((f) => f.path) };
    emit("job_progress", clone(jobs));
    for (const [phase, ms] of phases) {
      const steps = 8;
      for (let i = 1; i <= steps; i++) {
        await wait(ms / steps);
        const done = Math.round((total * i) / steps);
        emit("index_progress", { phase, done, total, current: all[Math.min(total - 1, done)]?.path ?? null, elapsedMs: big(performance.now() - t0) });
        if (phase === "walk" && i === steps) emit("tree_changed", null);
        if (phase === "parse") {
          const left = pending.slice(Math.round((pending.length * i) / steps));
          jobs = { ...jobs, queued: left.length, done: jobs.done + 1, cacheHits: jobs.cacheHits + big(total / steps), hitRate: 0.86, pendingFiles: left.map((f) => f.path) };
          emit("job_progress", clone(jobs));
        }
      }
    }
    pending.forEach((f) => (f.status = "indexed"));
    const fix = (n: TreeNode) => {
      if (n.isDir) {
        n.children.forEach(fix);
        n.status = n.children.some((c) => c.status === "pending") ? "pending" : "indexed";
      }
    };
    fix(tree);
    repo = { ...repo, indexed: all.filter((f) => f.status === "indexed").length };
    emit("index_progress", { phase: "done", done: total, total, current: null, elapsedMs: big(performance.now() - t0) });
    jobs = { ...jobs, queued: 0, running: 0, cacheMisses: big(pending.length), pendingFiles: [] };
    emit("job_progress", clone(jobs));
    emit("index_done", toRepoSummary(repo));
    indexing = false;
  }

  const delay = async <T>(v: T | (() => T)): Promise<T> => {
    if (LATENCY) await wait(LATENCY);
    return typeof v === "function" ? (v as () => T)() : v;
  };

  const allCards = (): { path: string; card: FnCard }[] =>
    Object.entries(files).flatMap(([path, f]) => f.view.functions.map((card) => ({ path, card })));

  return {
    kind: "mock",
    openRepo: (path) =>
      delay(() => {
        if (SIMULATE_INDEX) setTimeout(() => void simulateIndex(), 50);
        return toRepoSummary({ ...repo, root: path || repo.root });
      }),
    getTree: () => delay(() => clone(tree)),
    getFileView: (path) => delay(() => clone(fileFor(path).view)),
    getFlow: (path, unit) =>
      delay(() => {
        const u = fileFor(path).flows[unit];
        if (!u) throw new Error(`No flow unit ${unit} in ${path}`);
        return clone(u);
      }),
    getSource: (path, start, end) =>
      delay(() => {
        const f = fileFor(path);
        const lines = f.source.split("\n");
        const s = Math.max(1, start ?? 1);
        const e = Math.min(lines.length, end ?? lines.length);
        return { path, start: s, end: e, text: lines.slice(s - 1, e).join("\n"), monacoLang: f.view.monacoLang };
      }),
    getImpact: (symbol, transitive) =>
      delay(() => {
        const hit = allCards().find((x) => x.card.id === symbol);
        if (!hit) throw new Error(`Unknown symbol ${symbol}`);
        const { path, card } = hit;
        const view = files[path].view;
        const ref = (name: string, p: string, line: number, depth: number): SymRef => ({ id: card.id.slice(0, 8) + name.length.toString(16).padStart(8, "0"), name, path: p, line, confidence: "heuristic", depth });
        const dependents: SymRef[] = [];
        view.importers.slice(0, Math.max(1, card.externalCallers)).forEach((imp, i) => {
          dependents.push(ref(["registerHarness", "runEmbeddedAttempt", "handleAgentTurn"][i % 3], imp.path, (imp.line ?? 1) + 20 + i * 7, 1));
        });
        if (transitive) dependents.push(ref("startGateway", "src/gateway/server.ts", 88, 2), ref("main", "src/cli/run.ts", 41, 3));
        const dependencies = card.calls.map((c) => {
          const d = view.functions.find((f) => f.name === c)!;
          return { id: d.id, name: d.name, path, line: d.start, confidence: "exact" as const, depth: 1 };
        });
        return { symbol: { id: card.id, name: card.name, path, line: card.start, confidence: "exact", depth: 0 }, dependents, dependencies, filesAffected: new Set(dependents.map((d) => d.path)).size };
      }),
    getModuleMap: () => delay(() => ({ ...clone(moduleMap), modules: moduleMap.modules.map(toModuleInfo) })),
    getArchitecture: () => delay(() => clone(architecture)),
    search: (query, limit = 50) =>
      delay(() => {
        const q = query.trim().toLowerCase();
        if (!q) return [];
        const hits: SearchHit[] = [];
        const score = (s: string) => {
          const l = s.toLowerCase();
          const i = l.indexOf(q);
          if (i < 0) return 0;
          return (l === q ? 3 : l.startsWith(q) ? 2 : 1) + 1 / (1 + i) + 1 / (1 + l.length);
        };
        for (const { path, card } of allCards()) {
          const sc = score(card.name);
          if (sc) hits.push({ kind: "symbol", name: card.name, path, line: card.start, symbolKind: card.kind, score: sc + 0.5 });
        }
        for (const [path, f] of Object.entries(files)) {
          for (const t of f.view.types) {
            const sc = score(t.name);
            if (sc) hits.push({ kind: "symbol", name: t.name, path, line: t.start, symbolKind: t.kind, score: sc + 0.4 });
          }
          for (const o of f.view.outline) {
            const sc = score(o.name);
            if (sc) hits.push({ kind: "symbol", name: o.name, path, line: o.start, symbolKind: o.kind, score: sc + 0.4 });
          }
        }
        for (const n of leaves(tree)) {
          const sc = Math.max(score(n.name), score(n.path) * 0.8);
          if (sc) hits.push({ kind: "file", name: n.name, path: n.path, line: null, symbolKind: null, score: sc });
        }
        return hits.sort((a, b) => b.score - a.score || a.path.localeCompare(b.path)).slice(0, limit);
      }),
    aiStatus: () => delay(() => clone(ai)),
    aiSignIn: () =>
      delay(() => {
        ai = { ...ai, sidecar: "starting", deviceCode: { userCode: "MOCK-1234", verificationUri: "https://github.com/login/device" }, message: "The mock signs in by itself in 3 seconds." };
        clearTimeout(signInTimer);
        signInTimer = setTimeout(() => {
          ai = {
            ...ai,
            sidecar: "ready",
            signedIn: true,
            user: "mock-user",
            deviceCode: null,
            message: null,
            models: [
              { id: "mock-small", name: "Mock small", inputPerM: 0.1, outputPerM: 0.5 },
              { id: "mock-large", name: "Mock large", inputPerM: 1, outputPerM: 5 },
            ],
          };
        }, 3000);
        return clone(ai);
      }),
    aiSignInCancel: () =>
      delay(() => {
        clearTimeout(signInTimer);
        ai = { ...ai, sidecar: "off", deviceCode: null, message: null };
        return clone(ai);
      }),
    aiSignOut: () => delay(() => (ai = { ...ai, sidecar: "off", signedIn: false, user: null, models: [], deviceCode: null, message: null, enabledForRepo: false })),
    aiEstimate: (scope, path) =>
      delay(() => {
        const symbols = scope === "file" && path ? fileFor(path).view.functions.length : scope === "module" ? 120 : repo.files * 6;
        const cached = scope === "file" && path ? fileFor(path).view.functions.filter((f) => f.summary).length : Math.round(symbols * 0.4);
        const left = symbols - cached;
        const tokensIn = left * 900;
        const tokensOut = left * 120;
        return { scope, symbols, cached, requests: Math.ceil(left / 8), tokensIn: big(tokensIn), tokensOut: big(tokensOut), costUsd: (tokensIn * 0.1 + tokensOut * 0.5) / 1e6, model: "mock-small" };
      }),
    aiReview: (cmp) =>
      delay(() => {
        if (!ai.enabledForRepo) throw new Error("AI analysis is off for this repo. Turn it on first; no code leaves the machine until then.");
        const review = reviews.get(cmp.base.sha + cmp.head.sha) ?? null;
        return { review: review && clone(review), costUsd: review ? 0 : 0.012 + cmp.files.length * 0.0011, tokensIn: big(review ? 0 : 6000 + cmp.files.length * 900), model: "mock-large", filesWithoutPatch: 0 };
      }),
    aiReviewRun: (cmp, budgetUsd) =>
      new Promise((resolve, fail) =>
        setTimeout(() => {
          if (!ai.enabledForRepo) return fail(new Error("AI analysis is off for this repo."));
          const cost = 0.012 + cmp.files.length * 0.0011;
          if (cost > budgetUsd) return fail(new Error(`The review is estimated at $${cost.toFixed(4)}, over the budget of $${budgetUsd.toFixed(4)}.`));
          const r = mockReview(cmp);
          reviews.set(cmp.base.sha + cmp.head.sha, r);
          resolve(clone(r));
        }, 1400),
      ),
    aiRun: async (scope, path, budgetUsd) => {
      const estimate = await (async () => {
        const symbols = scope === "file" && path ? fileFor(path).view.functions.length : 120;
        return { scope, symbols, cached: 0, requests: Math.ceil(symbols / 8), tokensIn: big(symbols * 900), tokensOut: big(symbols * 120), costUsd: Math.min(budgetUsd, symbols * 0.00015), model: "mock-small" };
      })();
      const jobId = big(nextJob++);
      const total = estimate.symbols;
      let done = 0;
      const tick = () => {
        done = Math.min(total, done + Math.max(1, Math.ceil(total / 6)));
        const finished = done >= total;
        emit("ai_progress", { jobId, done, total, tokensIn: big(done * 900), tokensOut: big(done * 120), costUsd: done * 0.00015, finished, error: null });
        if (!finished) setTimeout(tick, 350);
        else {
          if (path) {
            const f = fileFor(path);
            f.view.functions.forEach((c) => {
              c.summary ??= { desc: `Runs ${c.name} (mock summary written by the AI run).`, algo: ["Takes its arguments as given.", "Returns the first one."], notes: [], model: "mock-small", ai: true };
            });
            f.view.overview ??= { text: `Mock overview of ${path}, written by the AI run.`, model: "mock-small" };
            emit("summary_ready", { path });
          }
          if (scope === "architecture" || scope === "repo") architecture = mockArchitecture(moduleMap);
          emit("ai_job_done", { jobId, stored: total, failed: 0, costUsd: total * 0.00015, error: null });
        }
      };
      setTimeout(tick, 300);
      await wait(LATENCY);
      return { jobId, estimate };
    },
    aiEnable: (enabled) => delay(() => (ai = { ...ai, enabledForRepo: enabled })),
    getJobs: () => delay(() => clone(jobs)),
    renameModule: (id, name, color) =>
      delay(() => {
        const m = moduleMap.modules.find((x) => x.id === id);
        if (!m) throw new Error(`Unknown module ${id}`);
        if (name) m.name = name;
        if (color) m.color = color;
        m.source = "user";
        const recolor = (n: TreeNode) => {
          if (n.module === id && color) n.color = color;
          n.children.forEach(recolor);
        };
        recolor(tree);
        tree = { ...tree };
        return toModuleInfo(clone(m));
      }),
    recentRepos: () => delay(() => clone(D.recent)),
    launchArgs: async () => {
      const q = new URLSearchParams(location.search);
      return { repo: q.get("repo"), open: q.get("open") };
    },
    pickFolder: () => delay(() => D.repo.root),
    gitStatus: () => delay(() => git.status()),
    gitRefs: () => delay(() => git.refs()),
    gitSwitch: (name, create) =>
      delay(() => {
        const s = git.switchTo(name, create);
        setTimeout(() => {
          emit("git_changed", s);
          emit("tree_changed", null);
        }, 30);
        return s;
      }),
    gitFetch: async () => {
      await wait(600);
      const s = git.fetch();
      emit("git_changed", s);
      return s;
    },
    gitPrs: () => delay(() => git.prs()),
    compare: async (base, head, threeDot, pr) => {
      await wait(250);
      return git.compare(base, head, threeDot, pr, sourceOf);
    },
    compareFile: (base, head, path, oldPath) => delay(() => git.compareFile(base, head, path, oldPath, sourceOf)),
    listen: async (event, cb) => {
      let set = listeners.get(event);
      if (!set) listeners.set(event, (set = new Set()));
      const f = cb as (p: unknown) => void;
      set.add(f);
      return () => set!.delete(f);
    },
  };
}

function summarize(tree: TreeNode): RawRepo {
  const all: TreeNode[] = [];
  const walk = (n: TreeNode) => (n.isDir ? n.children.forEach(walk) : all.push(n));
  walk(tree);
  const tiers = { full: 0, outline: 0, text: 0 };
  const langs = new Map<string, { lang: Language; label: string; files: number; lines: number }>();
  for (const f of all) {
    tiers[(f.tier ?? "text") as Tier]++;
    const lang = f.lang ?? "other";
    const c = langs.get(lang) ?? { lang, label: LANG_LABEL[lang] ?? lang, files: 0, lines: 0 };
    c.files++;
    c.lines += f.lines;
    langs.set(lang, c);
  }
  return {
    root: "~/code/monorepo",
    name: tree.name,
    files: all.length,
    lines: all.reduce((s, f) => s + f.lines, 0),
    tiers,
    languages: [...langs.values()].sort((a, b) => b.lines - a.lines),
    indexed: all.filter((f) => f.status === "indexed").length,
    rootHash: null,
    aiEnabled: false,
  };
}

const LANG_LABEL: Record<string, string> = { typescript: "TypeScript", tsx: "TSX", java: "Java", csharp: "C#", javascript: "JavaScript", python: "Python", rust: "Rust", go: "Go", markdown: "Markdown", json: "JSON", css: "CSS", yaml: "YAML", other: "Plain text" };
const MONACO: Record<string, string> = { typescript: "typescript", tsx: "typescript", javascript: "javascript", jsx: "javascript", python: "python", rust: "rust", go: "go", markdown: "markdown", json: "json", css: "css", yaml: "yaml", html: "html", java: "java", csharp: "csharp" };

/** A small, plausible file for tree entries the build script did not detail. */
function generatedFile(node: TreeNode): MockFile {
  const lang = (node.lang ?? "other") as Language;
  const tier = (node.tier ?? "text") as Tier;
  const base = node.name.replace(/\.[^.]+$/, "").replace(/[^A-Za-z0-9]+(.)/g, (_, c: string) => c.toUpperCase());
  const stem = base.charAt(0).toLowerCase() + base.slice(1) || "module";
  const module = node.module ? { id: node.module, name: node.module, color: node.color ?? "#5b6676" } : null;
  const common = {
    path: node.path,
    name: node.name,
    lang,
    langLabel: LANG_LABEL[lang] ?? lang,
    monacoLang: MONACO[lang] ?? "plaintext",
    tier,
    contentHash: "0000000000000000",
    types: [],
    modules: [],
    importsRange: null,
    importers: [],
    overview: null,
    hasErrors: false,
    module,
    targets: [] as FileView["targets"],
  };
  if (tier === "full" && (lang === "typescript" || lang === "javascript")) {
    const src = [
      `// ${node.name}: generated by the mock backend.`,
      ``,
      `export function ${stem}Init(options: Record<string, unknown> = {}) {`,
      `  const state = ${stem}Load(options);`,
      `  return ${stem}Handle(state);`,
      `}`,
      ``,
      `function ${stem}Load(options: Record<string, unknown>) {`,
      `  return { ...options, loadedAt: Date.now() };`,
      `}`,
      ``,
      `function ${stem}Handle(state: { loadedAt: number }) {`,
      `  if (state.loadedAt > 0) {`,
      `    return true;`,
      `  }`,
      `  return false;`,
      `}`,
      ``,
    ].join("\n");
    const card = (name: string, start: number, end: number, level: number, calls: string[], calledBy: string[], exported: boolean): FnCard => ({
      id: (node.path + name).split("").reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7).toString(16).padStart(16, "0"),
      name,
      qualifiedName: name,
      kind: "function",
      start,
      end,
      exported,
      isAsync: false,
      signature: src.split("\n")[start - 1].replace(/\s*\{$/, ""),
      doc: null,
      level,
      calls,
      calledBy,
      uses: [],
      typeUses: [],
      externalCallers: exported ? 1 : 0,
      summary: null,
      unit: name,
      sig: {
        params: name.endsWith("Init")
          ? [{ name: "options", typeText: "Record<string, unknown>", default: "{}", rest: false, optional: true }]
          : name.endsWith("Load")
            ? [{ name: "options", typeText: "Record<string, unknown>", default: null, rest: false, optional: false }]
            : [{ name: "state", typeText: "{ loadedAt: number }", default: null, rest: false, optional: false }],
        returns: null,
      },
    });
    const fns = [
      card(`${stem}Init`, 3, 6, 1, [`${stem}Load`, `${stem}Handle`], [], true),
      card(`${stem}Load`, 8, 10, 0, [], [`${stem}Init`], false),
      card(`${stem}Handle`, 12, 17, 0, [], [`${stem}Init`], false),
    ];
    const call = (label: string, id: string, line: number) => ({ t: "call" as const, label, target: { kind: "fn" as const, id }, line, await: false, optional: false, argOf: null, inner: [] });
    const flows: Record<string, FlowUnit> = {
      [`${stem}Init`]: { id: `${stem}Init`, owner: `${stem}Init`, method: null, start: 3, end: 6, async: false, params: ["options = …"], tree: [call(`${stem}Load`, `${stem}Load`, 4), call(`${stem}Handle`, `${stem}Handle`, 5), { t: "exit", kind: "return", label: `${stem}Handle(state)`, line: 5, early: false }] },
      [`${stem}Load`]: { id: `${stem}Load`, owner: `${stem}Load`, method: null, start: 8, end: 10, async: false, params: ["options"], tree: [{ t: "call", label: "Date.now", target: { kind: "builtin" }, line: 9, await: false, optional: false, argOf: null, inner: [] }, { t: "exit", kind: "return", label: "{ ...options, loadedAt: Date.now() }", line: 9, early: false }] },
      [`${stem}Handle`]: { id: `${stem}Handle`, owner: `${stem}Handle`, method: null, start: 12, end: 17, async: false, params: ["state"], tree: [{ t: "block", kind: "cond", kw: "if", label: "(state.loadedAt > 0)", line: 13, children: [{ t: "exit", kind: "return", label: "true", line: 14, early: true }] }, { t: "exit", kind: "return", label: "false", line: 16, early: false }] },
    };
    return {
      source: src,
      flows,
      view: {
        ...common,
        targets: [
          ...fns.map((f) => ({ name: f.name, origin: "local" as const, kind: "function" as const, path: node.path, start: f.start, end: f.end, module: null, doc: null, signature: f.signature })),
          ...["Record", "string", "unknown", "number"].map((name) => ({ name, origin: "builtin" as const, kind: null, path: null, start: 0, end: 0, module: null, doc: null, signature: null })),
        ],
        lines: src.split("\n").length - 1, layers: 2, functions: fns, outline: [], flowUnits: fns.map((f) => ({ id: f.name, owner: f.name, method: null, start: f.start, end: f.end, summary: null })) },
    };
  }
  const src =
    lang === "json"
      ? `{\n  "name": "${node.name}",\n  "private": true,\n  "generatedBy": "the mock backend"\n}\n`
      : lang === "css"
        ? `/* ${node.name}: generated by the mock backend. */\n.panel {\n  display: grid;\n  gap: 8px;\n}\n`
        : lang === "markdown"
          ? `# ${node.name}\n\nGenerated by the mock backend for ${node.path}.\n`
          : `${node.name}\n\nGenerated by the mock backend for ${node.path}.\n`;
  return { source: src, flows: {}, view: { ...common, lines: src.split("\n").length - 1, layers: 0, functions: [], outline: [], flowUnits: [] } };
}

/** What the mock's repo pass writes: three layers by module size and two flows along the
 * module graph's edges. */
function mockArchitecture(map: RawModuleMap): Architecture {
  const ids = map.modules.map((m) => m.id);
  const third = Math.max(1, Math.ceil(ids.length / 3));
  const path = (start: string) => {
    const out = [start];
    while (out.length < 4) {
      const next = map.edges.find((e) => e.from === out[out.length - 1] && !out.includes(e.to));
      if (!next) break;
      out.push(next.to);
    }
    return out;
  };
  const starts = [...new Set(map.edges.map((e) => e.from))];
  const flows = starts
    .map(path)
    .filter((p) => p.length >= 3)
    .slice(0, 2)
    .map((modules, i) => ({ name: i === 0 ? "Run a command" : "Deliver a message", text: "The mock writes this flow from the module graph: data moves along the edges shown here.", modules }));
  return {
    overview: `The mock repository has ${ids.length} modules. The entry points take a command, the core modules run it, and the foundations keep the shared types and settings.`,
    layers: [
      { name: "Entry points", modules: ids.slice(0, third) },
      { name: "Core", modules: ids.slice(third, third * 2) },
      { name: "Foundations", modules: ids.slice(third * 2) },
    ].filter((l) => l.modules.length),
    flows,
    model: "mock-large",
    modules: ids.length,
    writtenAt: Math.floor(Date.now() / 1000),
  };
}

/** A review that reads like the live one, built from the comparison's facts. */
function mockReview(cmp: Comparison): ChangeReview {
  const life = cmp.files.find((f) => f.path.endsWith("harness/lifecycle.ts"));
  const retry = cmp.files.find((f) => f.path.endsWith("retry-policy.ts"));
  const config = cmp.files.find((f) => f.path.endsWith("config/config.ts"));
  const notes: ChangeReview["notes"] = [];
  const legacy = cmp.impact.find((i) => i.symbol === "legacyAttemptTimeout");
  if (legacy) notes.push({ kind: "risk", text: `The change deletes legacyAttemptTimeout, but ${legacy.callerFiles} unchanged files still call it. Those calls fail at build time.`, path: legacy.path, symbol: legacy.symbol });
  if (config) notes.push({ kind: "risk", text: "getRuntimeConfigSnapshot now takes one options object. Callers that pass positional arguments get the defaults without a warning.", path: config.path, symbol: "getRuntimeConfigSnapshot" });
  if (retry) notes.push({ kind: "check", text: "The retry policy waits longer after each failure. Make sure that the total wait stays under the attempt timeout.", path: retry.path, symbol: null });
  if (life) notes.push({ kind: "info", text: "Finalization no longer takes the legacy flag: the lifecycle always runs the new cleanup order.", path: life.path, symbol: "runAgentHarnessLifecycleFinalization" });
  return {
    summary: `${cmp.pr ? `Pull request #${cmp.pr.number} ` : "The change "}adds a retry policy for harness attempts that fail for a temporary reason. The lifecycle asks the policy if it must try again and how long it must wait. The change also removes the legacy timeout path and moves configuration reads to one options object.`,
    notes,
    modules: cmp.modules.map((m) => ({ id: m.id, text: m.id === "agents-harness" ? "Gets the retry policy and a simpler finalization step." : m.id === "config" ? "Changes the snapshot call to take one options object." : `Changes ${m.files === 1 ? "one file" : `${m.files} files`}.` })),
    model: "mock-large",
    filesWithoutPatch: 0,
  };
}
